#!/usr/bin/env python3
"""flatten.py -- MariaDB Connector/C's mysql.h as ONE header, for 'tiko c2t'.

    python3 -I flatten.py <installed include/mariadb dir> <mariadb.h>

mysql.h is not one header but six: mariadb_com.h, mariadb_stmt.h, ma_list.h, mariadb_version.h
and mariadb_ctype.h are fragments that use mysql.h's types and are only valid at the point
mysql.h includes them -- mariadb_stmt.h needs MYSQL_RES, declared above its #include -- so each
fails to translate on its own (claude-docs docs/tiko-vendor RFC-0003 P0). c2t takes one header
per run, so this writes mysql.h with each quoted #include of a file in the same directory
replaced by that file's text, once, in the order mysql.h reaches them.

Also changed, and nothing else:
  - <custom_conf.h> (mariadb_version.h, inside #ifdef _CUSTOMCONFIG_) is dropped: it is not shipped;
  - mariadb_version.h is GENERATED by CMake per build host, and three of its lines are that host:
    MARIADB_SYSTEM_TYPE ("Windows" / "Linux"), MARIADB_MACHINE_TYPE ("AMD64" / "x86_64") and
    MARIADB_PLUGINDIR -- the build tree's absolute path, and meaningless here: every plugin
    vendor/mariadb ships is built in. The three are dropped; mariadb-residue.ti defines the first
    two per target. With them gone, the Windows and Linux builds' headers flatten to the same bytes;
  - line endings are LF.

The output is deterministic: the same input gives the same bytes.
"""
import os
import re
import sys

INC = re.compile(r'^\s*#\s*include\s+"([^"]+)"\s*$')
CUSTOM = re.compile(r'^\s*#\s*include\s+<custom_conf\.h>')
HOSTLINE = re.compile(r'^\s*#\s*define\s+(MARIADB_SYSTEM_TYPE|MARIADB_MACHINE_TYPE|MARIADB_PLUGINDIR)\b')


def expand(src, name, done):
    done.add(name)
    out = [f"/* ---- {name} ---- */\n"]
    with open(os.path.join(src, name), encoding="utf-8", newline="") as f:
        for line in f:
            line = line.replace("\r\n", "\n")
            m = INC.match(line)
            if m and os.path.exists(os.path.join(src, m.group(1))):
                if m.group(1) not in done:
                    out += expand(src, m.group(1), done)
                continue
            if CUSTOM.match(line):
                continue
            if HOSTLINE.match(line):
                out.append(f"/* {line.strip().split()[1]}: dropped by flatten.py -- see mariadb-residue.ti */\n")
                continue
            out.append(line)
    return out


def main():
    if len(sys.argv) != 3:
        sys.exit(__doc__)
    src, dst = sys.argv[1], sys.argv[2]
    lines = expand(src, "mysql.h", set())
    with open(dst, "w", encoding="utf-8", newline="\n") as f:
        f.writelines(lines)


if __name__ == "__main__":
    main()
